from content_helpers import code, output, choice, lesson, section, program
from content_06 import with_functions, example

def sections():
    return [section("microscope", "13. C++ под микроскопом", "Точные гарантии вместо удобных, но неверных правил.", [
        lesson("constants", "const и constexpr", "Разделите неизменяемость и вычисление при компиляции.",
            "const int limit=10; запрещает менять limit после инициализации. const не означает, что значение обязательно известно при компиляции: const int value=read(); может получить результат во время выполнения. constexpr int limit=10; требует константное выражение для такой переменной.\n\nconstexpr-функция может участвовать в вычислении при компиляции, если вызов удовлетворяет требованиям, но также может вызываться с обычным вводом во время выполнения. static_assert(condition, \"message\"); проверяет константное условие при компиляции.\n\nconst int* p не позволяет менять int через p, но сам p можно переназначать. int* const p не позволяет переназначить указатель, но позволяет менять исходный неконстантный int через *p. Не снимайте const ради изменения изначально const-объекта.",
            example('constexpr int twice(int n) { return 2 * n; }\nstatic_assert(twice(3) == 6, "wrong result");', 'int n = 0;\nstd::cin >> n;\nstd::cout << twice(n);'),
            "Неизменяемый доступ не тождественен глобальной неизменяемости объекта: const-ссылка на обычный int не мешает владельцу изменить тот же int через другое разрешённое имя. Для изначально const-объекта попытка изменения через снятие const уже недопустима.",
            "const ограничивает изменение, constexpr добавляет требования к константным вычислениям, static_assert проверяет их при сборке.", [
                with_functions(code("constexpr", "Вычисление в двух режимах", 'Напишите constexpr int square(int n), добавьте static_assert(square(4)==16). main читает n (−100…100) и выводит square(n).', 'int n = 0;\nstd::cin >> n;\nstd::cout << square(n);', [("7", "49"), ("-3", "9")], ["constexpr-функция всё ещё может принимать runtime-аргумент.", "static_assert используйте с известным при компиляции аргументом 4."], "Одна функция пригодна и для константного теста, и для пользовательского ввода."), 'constexpr int square(int n) { return n * n; }\nstatic_assert(square(4) == 16, "square contract");'),
                code("constref", "Читающий доступ", 'Ввод: n (−100…100). Создайте int value=n и const int& view=value. Измените value на n+1 через исходное имя и выведите view.', 'int n = 0;\nstd::cin >> n;\nint value = n;\nconst int& view = value;\nvalue = n + 1;\nstd::cout << view;', [("4", "5"), ("-1", "0")], ["view — ссылка, не копия.", "const запрещает запись через view, но не через неконстантное value."], "Ограничение пути доступа не замораживает исходный объект для всех имён."),
                choice("runtime", "constexpr — всегда compile time?", 'Обязательно ли каждый вызов constexpr-функции выполняется при компиляции?', ["Нет, она также может вызываться с данными времени выполнения", "Да, иначе программа не компилируется", "Да, и поэтому ввод в main запрещён"], 0, ["Требование к функции и конкретному вызову — разные уровни.", "Константный контекст требует константного вычисления; обычный вызов может быть runtime."], "Не обещайте фиксированную физическую стратегию выполнения там, где язык допускает обычный вызов."),
                code("fixedpointer", "Постоянный адрес", 'Ввод: n (−100…100). Создайте int value=n, int* const p=&value. Измените *p прибавлением 2 и выведите value. Сам p не переназначайте.', 'int n = 0;\nstd::cin >> n;\nint value = n;\nint* const p = &value;\n*p += 2;\nstd::cout << value;', [("3", "5"), ("0", "2")], ["const относится к указателю после *.", "Объект value не const, поэтому запись через *p допустима."], "Размещение const меняет то, какая часть типа ограничена.")
            ], ["const", "constexpr", "static_assert"]),
        lesson("representations", "Знаки и преобразования", "Проверяйте диапазон до операции, которая теряет информацию.",
            "Беззнаковая арифметика выполняется по модулю 2^N для соответствующего типа: уменьшение нулевого unsigned на 1 даёт его максимальное значение. Это определённое правило, не signed overflow. Но смешивание signed и unsigned может неожиданно преобразовать отрицательное число в большое беззнаковое.\n\nstd::numeric_limits<T>::max() из <limits> сообщает максимальное значение типа, а digits — число значащих двоичных разрядов без знака для целых. Не фиксируйте int как ровно 32 бита в переносимой теории. Для более широкого произведения преобразуйте операнд до умножения: 1LL*a*b. Суффикс LL задаёт long long.\n\nПреобразование double в целое требует представимого результата после отбрасывания дробной части; не пытайтесь использовать его для произвольно огромного числа.",
            program('unsigned value = 0;\n--value;\nstd::cout << (value == std::numeric_limits<unsigned>::max());', "iostream limits"),
            "C++17 и C++20 различаются в некоторых формулировках знаковых представлений и целочисленных преобразований. В курсе не используем спорное преобразование большого unsigned в signed как задачу на один переносимый ответ для обоих стандартов. Явно выбранные безопасные диапазоны работают в обоих.",
            "Диапазон и знаковость — часть алгоритма. Расширяйте до операции, а не после переполнения.", [
                code("wide", "Большая площадь", 'Ввод: a,b (0…100000). Объявите их long long, выведите произведение. Не используйте int для входных переменных.', 'long long a = 0, b = 0;\nstd::cin >> a >> b;\nstd::cout << a * b;', [("100000 100000", "10000000000"), ("0 99999", "0")], ["Предел 100000 уже не гарантирован для минимального int.", "Оба операнда long long дают подходящий диапазон произведения."], "Выбор типа происходит до чтения и вычисления, а не после потери диапазона."),
                code("checkrange", "Безопасное сужение", 'Ввод: long long n от −100000 до 100000. Если n находится в диапазоне −100…100, преобразуйте в int и выведите его. Иначе выведите Outside.', 'long long n = 0;\nstd::cin >> n;\nif (-100 <= n && n <= 100) {\n    std::cout << static_cast<int>(n);\n} else { std::cout << "Outside"; }', [("100", "100"), ("-100", "-100"), ("101", "Outside")], ["Проверка должна происходить в исходном широком типе.", "Вызов static_cast<int> поместите только внутрь допустимой ветви."], "Проверка после преобразования уже могла бы анализировать изменённое значение."),
                output("unsigned", "Определённый модуль", 'unsigned value = 0;\n--value;\nstd::cout << (value == std::numeric_limits<unsigned>::max());', "1", ["Это unsigned, не знаковый int.", "Модульная арифметика делает предыдущее перед 0 значение максимальным."], "Точный максимум зависит от типа, но сравнение с его собственным max переносимо.", headers="iostream limits"),
                code("promote", "Расширение до умножения", 'Ввод: a,b (0…100), прочитайте в int. Выведите 1LL*a*b*1000000, гарантируя wide-тип с первой операции.', 'int a = 0, b = 0;\nstd::cin >> a >> b;\nstd::cout << 1LL * a * b * 1000000;', [("100 100", "10000000000"), ("2 3", "6000000")], ["Литерал 1LL имеет тип long long.", "Поставьте его слева в цепочке умножений."], "Более широкий тип участвует до потенциально большого промежуточного результата.")
            ], ["signed", "unsigned", "преобразования"]),
        lesson("undefined", "Неопределённое поведение", "Исправляйте причину, не угадывайте результат нарушения.",
            "Undefined behavior означает отсутствие требований стандарта к поведению выполнения, которое дошло до такого нарушения. Это не обязательно исключение, зависание или ноль. Примеры для C++17/20: знаковое переполнение, целочисленное деление на ноль, чтение через висячий указатель, выход за границы допустимых элементов. Не задавайте точный вывод такой программы как однозначный тест.\n\nОтличайте implementation-defined: реализация выбирает и документирует вариант (например, определённые характеристики типов), и unspecified: допустим один из нескольких вариантов без требования документировать конкретный выбор. Не всякая непривычная программа имеет UB: unsigned модуль и -17/5 определены.\n\nЗащитный код проверяет предусловия до опасной операции. Проверки компилятора и санитайзеры полезны, но отсутствие предупреждения не доказывает отсутствие UB.",
            program('int a = 12, b = 0;\nif (b == 0) { std::cout << "Invalid divisor"; }\nelse { std::cout << a / b; }'),
            "Оптимизатор имеет право исходить из соблюдения правил языка на определённых выполнениях. Поэтому рассуждение «процессор обычно делает вот так» не исправляет UB в исходной программе. Проверяйте утверждения по выбранному стандарту, не по одному запуску.",
            "У UB нет фиксированного ожидаемого ответа. Сначала исключите нарушение, затем анализируйте результат.", [
                code("divide", "Проверенный делитель", 'Ввод: a (−100…100), b (−10…10). При b=0 выведите Invalid, иначе целочисленное a/b. Проверяйте до деления.', 'int a = 0, b = 0;\nstd::cin >> a >> b;\nif (b == 0) { std::cout << "Invalid"; }\nelse { std::cout << a / b; }', [("12 0", "Invalid"), ("-17 5", "-3"), ("9 3", "3")], ["Не вычисляйте частное до if.", "Опасная операция должна находиться только в else."], "Ограничения также исключают крайний случай минимального int / -1."),
                code("index", "Проверенный индекс", 'Ввод: index (−5…8). Массив фиксирован: {4,7,9}. Выведите значение при 0≤index<3, иначе Invalid.', 'int data[3] = {4, 7, 9};\nint index = 0;\nstd::cin >> index;\nif (0 <= index && index < 3) { std::cout << data[index]; }\nelse { std::cout << "Invalid"; }', [("0", "4"), ("2", "9"), ("3", "Invalid"), ("-1", "Invalid")], ["Нужно проверить и нижнюю, и верхнюю границы.", "Не считывайте data[index] в промежуточную переменную до проверки."], "Проверка должна защищать сам момент доступа, а не только последующий вывод."),
                choice("ub", "Что выведет ошибка?", 'Какой единственный переносимый ответ на вопрос о точном результате чтения через удалённый int*?', ["Всегда старое число", "Всегда исключение", "Точного гарантированного результата нет: такое чтение недопустимо"], 2, ["Старые байты не означают живой объект.", "Стандарт не обещает определённый симптом UB."], "Правильная учебная задача просит найти нарушение и исправить его, а не угадать один запуск."),
                code("boundsum", "Сложение с малым контрактом", 'Ввод: a,b (−1000…1000). Выведите их сумму, но если она вне разрешённого прикладного диапазона −100…100 — выведите Limit. Все промежуточные значения по условию представимы в int.', 'int a = 0, b = 0;\nstd::cin >> a >> b;\nint sum = a + b;\nif (-100 <= sum && sum <= 100) { std::cout << sum; }\nelse { std::cout << "Limit"; }', [("70 40", "Limit"), ("-50 20", "-30"), ("100 0", "100")], ["Здесь сумма до проверки безопасна по ограничению ±2000.", "Не путайте прикладной диапазон с переполнением типа."], "Когда промежуточное вычисление гарантированно представимо, проверка его прикладного диапазона после вычисления корректна.")
            ], ["UB", "предусловия", "гарантии стандарта"])
    ])]
